// handleAmendCommitMsg handles the prepare-commit-msg hook for amend operations
// (source="commit"). It preserves existing trailers or restores from LastCheckpointID.
func (s *ManualCommitStrategy) handleAmendCommitMsg(ctx context.Context, commitMsgFile string, strippedDeleted bool) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	// Read current commit message
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return nil
	}

	message := string(content)

	// If the final trailer block already has a live trailer, keep it unchanged;
	// an ID elsewhere in the message is not this commit's link. A deleted ID
	// still mentioned somewhere (not as a whole trailer line, so not stripped)
	// does not count: preserving on it would keep the dead checkpoint linked.
	// Every final-block trailer is also a mention, so a message without one
	// skips reading the comment prefix from git config.
	if mentioned := trailers.ParseAllCheckpoints(message); len(mentioned) > 0 {
		if live := withoutDeletedCheckpoints(ctx, preparedFinalTrailers(message, gitCommentPrefix(ctx, message))); len(live) > 0 {
			logging.Debug(logCtx, "prepare-commit-msg: amend preserves existing trailer",
				slog.String("strategy", "manual-commit"),
				slog.String("checkpoint_id", live[0].String()),
			)
			return nil
		}
		if len(withoutDeletedCheckpoints(ctx, mentioned)) == 0 {
			strippedDeleted = true
		}
	}

	// No trailer in message — check if any session has LastCheckpointID to restore
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil
	}

	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		return nil
	}

	// For amend, HEAD^ is the commit being amended, and HEAD is where we are now.
	// We need to match sessions whose BaseCommit equals HEAD (the commit being amended
	// was created from this base). This prevents stale sessions from injecting
	// unrelated checkpoint IDs.
	repo, repoErr := OpenRepository(ctx)
	if repoErr != nil {
		return nil
	}
	defer repo.Close()
	head, headErr := repo.Head()
	if headErr != nil {
		return nil
	}
	currentHead := head.Hash().String()

	// Find first matching session with LastCheckpointID to restore.
	// LastCheckpointID is set after condensation completes.
	for _, state := range sessions {
		if state.BaseCommit != currentHead {
			continue
		}
		if state.LastCheckpointID.IsEmpty() {
			continue
		}
		// A delete lists the ID before clearing it from session state, so an
		// amend racing that window must not restore it.
		if len(withoutDeletedCheckpoints(ctx, []id.CheckpointID{state.LastCheckpointID})) == 0 {
			continue
		}
		cpID := state.LastCheckpointID
		source := "LastCheckpointID"

		// Restore the trailer
		message = addCheckpointTrailerAboveComments(message, cpID, gitCommentPrefix(ctx, message))
		if writeErr := os.WriteFile(commitMsgFile, []byte(message), 0o600); writeErr != nil { //nolint:gosec // path from git hook arg
			return nil
		}

		logging.Info(logCtx, "prepare-commit-msg: restored trailer on amend",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", cpID.String()),
			slog.String("session_id", state.SessionID),
			slog.String("source", source),
		)

	if !strings.Contains(result, "Claude Code session context") {
		t.Errorf("addCheckpointTrailerWithComment() should contain agent name in comment, got: %q", result)
	}

	// Should contain prompt line (after removal comment)
	if !strings.Contains(result, "# Last Prompt: add password hashing") {
		t.Errorf("addCheckpointTrailerWithComment() should contain prompt, got: %q", result)
	}

	// Verify order: Remove comment should come before Last Prompt
	removeIdx := strings.Index(result, "# Remove the Entire-Checkpoint")
	promptIdx := strings.Index(result, "# Last Prompt:")
	if promptIdx < removeIdx {
		t.Errorf("addCheckpointTrailerWithComment() prompt should come after remove comment, got: %q", result)
	}
}

